import random
import string
from typing import List, Tuple

# URL generator targeting Ada URL parsing and with-base parsing.
# Goal: produce valid, interesting ASCII/UTF-8 URL or URL-like strings that
# cover various components: scheme, authority (userinfo, host, port), path,
# query, fragment, IPv4/IPv6/IDNA/punycode hosts, opaque paths, relative refs,
# file/data/mailto schemes, edge cases like empty host, default ports, etc.

SCHEMES_ABSOLUTE = [
    "http", "https", "ws", "wss", "ftp", "gopher", "file",
]
SCHEMES_OPAQUE = [
    "mailto", "urn", "blob", "data",
]

COMMON_TLDS = [
    "com", "org", "net", "io", "dev", "xyz", "教育", "测试", "xn--p1ai"
]

PATH_SEGMENTS = [
    "", "~", "-", "_", ".", "..", "api", "v1", "users", "äö", "%20",
    "mixed-Case", "こんにちは", "spaces here", ";param", "(paren)", "中文"
]

QUERY_KEYS = [
    "q", "page", "sort", "filter", "utm_source", "token", "空", "emoji"
]

QUERY_VALUES = [
    "", "1", "true", "false", "asc", "desc", "hello world", "a%2Fb",
    "ümlaut", "你好", "😀", "%F0%9F%98%80"
]

FRAGMENTS = [
    "", "top", "section-1", "ä", "こんにちは", "line=10", "😀"
]

USERNAMES = ["", "user", "User.Name", "δοκιμή", "😀"]
PASSWORDS = ["", "pass", "p@ss:word", "секрет"]

# Reasonable default ports to sometimes include
DEFAULT_PORTS = {"http": 80, "https": 443, "ws": 80, "wss": 443, "ftp": 21}

MAX_TOTAL = 4096


def _rand(r: random.Random, seq: List[str]) -> str:
    return r.choice(seq)


def _maybe(r: random.Random, p: float) -> bool:
    return r.random() < p


def _gen_label(r: random.Random) -> str:
    # Mix ASCII, Unicode, and percent-encoded
    choices = [
        "example", "sub", "test", "δοκιμή", "пример", "例子", "münchen",
        "xn--d1acpjx3f",  # punycode for пример
    ]
    s = _rand(r, choices)
    # Sometimes add hyphens or digits
    if _maybe(r, 0.5):
        s += "-" + str(r.randint(0, 999))
    return s


def _gen_domain(r: random.Random) -> str:
    # 20% single-label (localhost), 60% multi-label, 20% unicode label
    mode = r.random()
    if mode < 0.2:
        return "localhost"
    labels = []
    for _ in range(r.randint(1, 3)):
        labels.append(_gen_label(r))
    tld = _rand(r, COMMON_TLDS)
    return ".".join(labels + [tld])


def _gen_ipv4(r: random.Random) -> str:
    return ".".join(str(r.randint(0, 255)) for _ in range(4))


def _gen_ipv6(r: random.Random) -> str:
    # Generate varied IPv6 forms; sometimes compressed
    def h():
        return format(r.randint(0, 0xFFFF), 'x')
    if _maybe(r, 0.5):
        # full 8 groups
        parts = [h() for _ in range(8)]
        return ":".join(parts)
    else:
        # compressed; choose k head, m tail
        k = r.randint(0, 6)
        m = r.randint(0, 6 - k)
        head = ":".join(h() for _ in range(k))
        tail = ":".join(h() for _ in range(m))
        if head and tail:
            return head + "::" + tail
        elif head:
            return head + "::"
        elif tail:
            return "::" + tail
        else:
            return "::"


def _gen_host(r: random.Random) -> str:
    t = r.random()
    if t < 0.55:
        return _gen_domain(r)
    elif t < 0.75:
        return _gen_ipv4(r)
    else:
        return "[" + _gen_ipv6(r) + "]"


def _pct_encode(s: str) -> str:
    out = []
    for ch in s:
        o = ord(ch)
        if (48 <= o <= 57) or (65 <= o <= 90) or (97 <= o <= 122) or ch in "-._~":
            out.append(ch)
        else:
            out.append('%%%02X' % (o if o < 256 else 0x20))
    return ''.join(out)


def _gen_path(r: random.Random, absolute: bool) -> str:
    segs = []
    n = r.randint(0, 5)
    for _ in range(n):
        seg = _rand(r, PATH_SEGMENTS)
        if _maybe(r, 0.4):
            seg = _pct_encode(seg)
        segs.append(seg)
    core = "/".join(segs)
    if absolute:
        return "/" + core if not core.startswith("/") else core
    else:
        if _maybe(r, 0.5):
            return core or ""
        # dot-segments leading for relative refs
        lead = _rand(r, ["./", "../", "../../", ""]) 
        return lead + core


def _gen_query(r: random.Random) -> str:
    parts = []
    n = r.randint(0, 5)
    for _ in range(n):
        k = _rand(r, QUERY_KEYS)
        v = _rand(r, QUERY_VALUES)
        if _maybe(r, 0.5):
            k = _pct_encode(k)
        if _maybe(r, 0.5):
            v = _pct_encode(v)
        parts.append(f"{k}={v}")
    if not parts and _maybe(r, 0.2):
        # lone key or empty query
        return "?" if _maybe(r, 0.5) else "?flag"
    return ("?" + "&".join(parts)) if parts else ""


def _gen_fragment(r: random.Random) -> str:
    frag = _rand(r, FRAGMENTS)
    if frag == "":
        return "" if _maybe(r, 0.7) else "#"
    if _maybe(r, 0.5):
        frag = _pct_encode(frag)
    return "#" + frag


def _gen_userinfo(r: random.Random) -> str:
    if not _maybe(r, 0.35):
        return ""
    user = _rand(r, USERNAMES)
    pwd = _rand(r, PASSWORDS) if _maybe(r, 0.6) else ""
    if _maybe(r, 0.5):
        user = _pct_encode(user)
    if pwd and _maybe(r, 0.5):
        pwd = _pct_encode(pwd)
    return f"{user}:{pwd}@" if pwd or user else "@"


def _gen_port(r: random.Random, scheme: str) -> str:
    if not _maybe(r, 0.4):
        return ""
    if scheme in DEFAULT_PORTS and _maybe(r, 0.5):
        port = DEFAULT_PORTS[scheme]
    else:
        port = r.choice([0, 1, 21, 80, 81, 123, 443, 8443, 65535, r.randint(2, 65534)])
    return f":{port}"


def _abs_url(r: random.Random) -> str:
    scheme_pool = SCHEMES_ABSOLUTE + SCHEMES_OPAQUE
    scheme = _rand(r, scheme_pool)

    if scheme in SCHEMES_OPAQUE and _maybe(r, 0.6):
        # Opaque-form like mailto:, data:, urn:
        if scheme == "mailto":
            local = _pct_encode(_rand(r, ["alice", "bob.smith", "δοκιμή"]))
            host = _gen_domain(r)
            path = f"{local}@{host}"
            q = _gen_query(r) if _maybe(r, 0.5) else ""
            frag = _gen_fragment(r)
            return f"{scheme}:{path}{q}{frag}"
        if scheme == "data":
            mime = _rand(r, ["text/plain", "image/png", "application/json"]) \
                   + (";charset=utf-8" if _maybe(r, 0.5) else "")
            payload = _rand(r, ["hello", "{\"a\":1}", "iVBORw0KGgo="])
            return f"data:{mime},{payload}"
        if scheme == "urn":
            nid = _rand(r, ["uuid", "isbn", "example"]) 
            nss = _pct_encode(_rand(r, ["123e4567-e89b-12d3-a456-426614174000", "9780316066525", "näme"]))
            return f"urn:{nid}:{nss}"
        # blob: URL typically wraps another URL; generate nested http URL
        inner = _http_like(r)
        return f"blob:{inner}"

    return _http_like(r, force_scheme=scheme)


def _http_like(r: random.Random, force_scheme: str | None = None) -> str:
    scheme = force_scheme if force_scheme else _rand(r, SCHEMES_ABSOLUTE)
    userinfo = _gen_userinfo(r)
    host = _gen_host(r) if _maybe(r, 0.9) else ""  # sometimes empty host
    port = _gen_port(r, scheme)
    # For file:, authority is optional; sometimes empty host is significant
    if scheme == "file" and _maybe(r, 0.5):
        authority = "///" if _maybe(r, 0.5) else "//" + host
    else:
        authority = "//" + userinfo + host + port
    path = _gen_path(r, absolute=True)
    query = _gen_query(r)
    fragment = _gen_fragment(r)
    return f"{scheme}:{authority}{path}{query}{fragment}"


def _relative_ref(r: random.Random) -> str:
    # Generate relative references including query/fragment
    path = _gen_path(r, absolute=False)
    if not path and _maybe(r, 0.4):
        path = "./"
    q = _gen_query(r)
    f = _gen_fragment(r)
    return f"{path}{q}{f}"


def _edge_cases(r: random.Random) -> List[str]:
    return [
        "http://example.com",  # canonical
        "https://example.com/path?x=1#frag",
        "http://user:pass@example.com:80/",
        "ftp://[2001:db8::1]/file.txt",
        "file:///C:/Windows/System32/",
        "file://localhost/etc/hosts",
        "//example.com/path" , # scheme-relative
        "../rel/path?x=1",
        "mailto:alice@example.com",
        "data:text/plain;charset=utf-8,hello%20world",
        "urn:uuid:123e4567-e89b-12d3-a456-426614174000",
        "http://例え.テスト/パス",
        "https://xn--fsq.com/",  # puny-like label
    ]


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Choose one of several URL families, with some probability mass on curated cases
    choice = r.random()
    if choice < 0.20:
        s = r.choice(_edge_cases(r))
    elif choice < 0.65:
        s = _abs_url(r)
    elif choice < 0.90:
        s = _http_like(r)
    else:
        s = _relative_ref(r)

    # Ensure ASCII/UTF-8 bytes; truncate to max total size and return
    b = s.encode('utf-8', errors='strict')
    if len(b) > MAX_TOTAL:
        b = b[:MAX_TOTAL]
    return b

import random
import string
from typing import List

# Host string generator for ada_set_host
# - Should return a bytes object representing a host component, optionally with a port
# - Valid examples include:
#   * domain names (ASCII, Unicode, punycode)
#   * IPv4 addresses
#   * IPv6 literals in brackets, optional port: [2001:db8::1]:443
# - The fuzzer stub slices the input to a random length, so we should provide strings
#   that remain valid across various prefixes. We'll bias toward complete, valid hosts
#   while also including forms where early prefixes are still syntactically acceptable.

MAX_LEN = 4096

ASCII_LABEL_CHARS = string.ascii_lowercase + string.digits + "-"
UNICODE_LABEL_SAMPLES = [
    "möwe",        # umlaut
    "café",        # accent
    "例子",         # CJK
    "δοκιμή",      # Greek
    "пример",      # Cyrillic
    "भारत",        # Devanagari
    "한국",          # Hangul
    "موقع",         # Arabic
]

PUNYCODE_SAMPLES = [
    "xn--bcher-kva",   # bücher
    "xn--caf-dma",     # café (one of possible punycode renderings for demonstration)
    "xn--fsqu00a",      # example (punycode demo)
]

# A selection of plausible TLDs
TLDS = [
    "com", "org", "net", "io", "dev", "xyz", "info", "co", "uk", "de", "jp", "cn", "edu",
]

COMMON_PORTS = ["80", "443", "8080", "8443", "21", "22", "25", "110", "143", "993", "3306", "5432"]

IPV6_BLOCKS = "0123456789abcdef"


def rand_choice(rng: random.Random, items: List[str]) -> str:
    return items[rng.randrange(len(items))]


def gen_label_ascii(rng: random.Random) -> str:
    # Generate an ASCII DNS label: 1..63 chars, no leading/trailing '-', not all numeric constraints here
    length = rng.randint(1, 20)
    while True:
        s = ''.join(rng.choice(ASCII_LABEL_CHARS) for _ in range(length))
        if s[0] == '-' or s[-1] == '-':
            continue
        return s


def gen_label_unicode(rng: random.Random) -> str:
    # Either pick from sample or construct a mixed label
    if rng.random() < 0.7:
        return rand_choice(rng, UNICODE_LABEL_SAMPLES)
    # Construct a simple mixed label with Latin + combining possibilities
    base = gen_label_ascii(rng)
    extra = rand_choice(rng, UNICODE_LABEL_SAMPLES)
    if rng.random() < 0.5:
        return extra + base
    else:
        return base + extra


def gen_domain(rng: random.Random) -> str:
    # Compose 2-4 labels, mix ascii/unicode/punycode
    parts = []
    n = rng.randint(2, 4)
    for i in range(n - 1):
        p = rng.random()
        if p < 0.6:
            parts.append(gen_label_ascii(rng))
        elif p < 0.85:
            parts.append(gen_label_unicode(rng))
        else:
            parts.append(rand_choice(rng, PUNYCODE_SAMPLES))
    parts.append(rand_choice(rng, TLDS))
    return ".".join(parts)


def gen_ipv4(rng: random.Random) -> str:
    # Sometimes include leading zeros or edge ranges
    def octet():
        choice = rng.random()
        if choice < 0.2:
            return str(rng.randint(0, 255))
        elif choice < 0.4:
            return str(rng.choice([0, 1, 10, 127, 169, 172, 192, 224, 255]))
        elif choice < 0.7:
            return str(rng.randint(200, 255))
        else:
            # add leading zeros but still decimal
            v = rng.randint(0, 255)
            width = rng.randint(2, 3)
            return f"{v:0{width}d}"
    return ".".join(octet() for _ in range(4))


def gen_ipv6(rng: random.Random) -> str:
    # Generate a compressed/expanded IPv6 literal, possibly with IPv4 tail
    def h16():
        n = rng.randint(1, 4)
        return ''.join(rng.choice(IPV6_BLOCKS) for _ in range(n))

    # Decide format
    fmt = rng.random()
    if fmt < 0.3:
        # Fully expanded 8 blocks
        parts = [f"{rng.randint(0, 0xFFFF):x}" for _ in range(8)]
        core = ":".join(parts)
    elif fmt < 0.6:
        # Compressed with :: once
        head_len = rng.randint(0, 6)
        tail_len = rng.randint(0, 6 - head_len)
        head = [h16() for _ in range(head_len)]
        tail = [h16() for _ in range(tail_len)]
        core = (":".join(head) if head else "") + "::" + (":".join(tail) if tail else "")
        if core == "::":
            pass
    else:
        # IPv6 with IPv4 tail
        head_len = rng.randint(0, 6)
        head = [h16() for _ in range(head_len)]
        ipv4 = gen_ipv4(rng)
        core = (":".join(head) + (":" if head else "")) + ipv4
        # Allow :: compression in head
        if rng.random() < 0.5:
            core = "::" + core
    return f"[{core}]"


def maybe_port(rng: random.Random) -> str:
    if rng.random() < 0.65:
        if rng.random() < 0.8:
            port = rand_choice(rng, COMMON_PORTS)
        else:
            port = str(rng.randint(1, 65535))
        return ":" + port
    return ""


def gen_host(rng: random.Random) -> str:
    kind = rng.random()
    if kind < 0.5:
        host = gen_domain(rng)
    elif kind < 0.75:
        host = gen_ipv4(rng)
    else:
        host = gen_ipv6(rng)
    # Ports allowed on domain and IPv4; for IPv6, port must be after closing bracket
    return host + maybe_port(rng)


def bias_for_prefix_validity(rng: random.Random, s: str) -> str:
    # The fuzzer may truncate; make sure early prefixes are still plausible.
    # Strategy: optionally prepend a subdomain so that slicing at different points
    # can leave a valid label or partial but still acceptable for can-parse checks.
    if rng.random() < 0.4 and not s.startswith('['):
        prefix = gen_label_ascii(rng)
        s = prefix + "." + s
    return s


def clamp_size(b: bytes) -> bytes:
    if len(b) > MAX_LEN:
        return b[:MAX_LEN]
    return b


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Create a small corpus bias with some hand-picked interesting cases
    corpus = [
        "localhost",
        "localhost:80",
        "example.com",
        "example.com:8080",
        "xn--bcher-kva.de",
        "bücher.example",
        "0.0.0.0",
        "255.255.255.255:65535",
        "[::1]",
        "[2001:db8::1]:443",
        "[::ffff:192.0.2.128]",
        "sub.domain.co.uk",
    ]

    if rng.random() < 0.4:
        s = rand_choice(rng, corpus)
    else:
        s = gen_host(rng)
        s = bias_for_prefix_validity(rng, s)

    # Ensure C-string friendly content (no embedded NUL). We'll avoid NUL entirely.
    # Encode as UTF-8 for Unicode cases.
    b = s.encode('utf-8', errors='strict')
    return clamp_size(b)

import random
import string
from typing import List

# Generator for domain/host labels to exercise IDNA conversions.
# We create a variety of valid Unicode hostnames, ASCII punycode, mixtures,
# different label counts, edge cases like empty labels, trailing dots, etc.

# Some representative Unicode characters commonly seen in IDNA examples
UNICODE_LABEL_SAMPLES = [
    "bücher",               # umlaut
    "mañana",               # tilde n
    "παράδειγμα",           # Greek
    "例子",                  # CJK
    "مثال",                 # Arabic
    "δοκιμή",               # Greek test
    "пример",               # Cyrillic
    "उदाहरण",              # Hindi
    "संगठन",               # Hindi org
    "えげれす",              # Hiragana
    "한국",                 # Korean
    "ยกตัวอย่าง",          # Thai
]

# Some pre-encoded punycode host samples
PUNYCODE_HOST_SAMPLES = [
    "xn--bcher-kva.example",         # bücher.example
    "xn--mnchen-3ya.de",             # münchen.de
    "xn--fsqu00a.xn--0zwm56d",       # 例子.测试 (example.test)
    "xn--e1afmkfd.xn--80akhbyknj4f", # пример.испытание (example.test)
    "xn--d1acufc.xn--p1ai",          # пример.рф
    "xn--hxajbheg2az3al.xn--jxalpdlp", # παράδειγμα.δοκιμή
]

ASCII_LABEL_SAMPLES = [
    "example", "test", "com", "net", "org", "localhost", "subdomain",
]

# IDNA valid label characters in ASCII range (pre-conversion)
ASCII_LABEL_CHARS = string.ascii_lowercase + string.digits + "-"

# Some separators and variants
SEPARATORS = [".", "..", ".", "."]

MAX_TOTAL_BYTES = 4096


def rand_ascii_label(rng: random.Random, min_len=1, max_len=20) -> str:
    # Ensure label does not start or end with '-'
    length = rng.randint(min_len, max_len)
    if length == 1:
        return rng.choice(string.ascii_lowercase + string.digits)
    middle_len = max(0, length - 2)
    start = rng.choice(string.ascii_lowercase + string.digits)
    middle = ''.join(rng.choice(ASCII_LABEL_CHARS) for _ in range(middle_len))
    end = rng.choice(string.ascii_lowercase + string.digits)
    return start + middle + end


def rand_unicode_label(rng: random.Random) -> str:
    # Choose from samples or compose by mixing sample pieces
    if rng.random() < 0.6:
        return rng.choice(UNICODE_LABEL_SAMPLES)
    # compose: pick 1-2 pieces and maybe insert combining marks
    base = rng.choice(UNICODE_LABEL_SAMPLES)
    if rng.random() < 0.4:
        base += rng.choice(["ñ", "ä", "ø", "å", "é", "ß", "ç", "ł"])
    return base


def maybe_trailing_dot(host: str, rng: random.Random) -> str:
    if rng.random() < 0.25 and not host.endswith('.'):
        return host + '.'  # FQDN style
    return host


def maybe_empty_labels(rng: random.Random) -> List[str]:
    # Occasionally include empty labels to make leading/trailing/consecutive dots
    parts = []
    if rng.random() < 0.1:
        parts.append("")  # leading empty label -> starts with dot
    return parts


def build_host(rng: random.Random) -> str:
    mode = rng.random()
    parts: List[str] = []

    # possibility of a wildcard-like or underscore label which can appear in some contexts
    def maybe_special_label() -> str:
        choices = ["_service", "_tcp", "_udp", "*",]
        return rng.choice(choices)

    if mode < 0.2:
        # Pure ASCII labels
        n = rng.randint(1, 5)
        parts = [rand_ascii_label(rng) for _ in range(n)]
    elif mode < 0.4:
        # Pure Unicode labels
        n = rng.randint(1, 4)
        parts = [rand_unicode_label(rng) for _ in range(n)]
    elif mode < 0.55:
        # Mixed ASCII + Unicode
        n = rng.randint(2, 6)
        for i in range(n):
            if rng.random() < 0.5:
                parts.append(rand_ascii_label(rng))
            else:
                parts.append(rand_unicode_label(rng))
    elif mode < 0.75:
        # Pre-encoded punycode host strings (already dotted)
        return rng.choice(PUNYCODE_HOST_SAMPLES)
    else:
        # Include some special labels and empty labels
        parts = maybe_empty_labels(rng)
        n = rng.randint(1, 5)
        for i in range(n):
            choice = rng.random()
            if choice < 0.1:
                parts.append("")  # empty label to create double dots
            elif choice < 0.25:
                parts.append(maybe_special_label())
            elif choice < 0.6:
                parts.append(rand_ascii_label(rng))
            else:
                parts.append(rand_unicode_label(rng))
        if rng.random() < 0.1:
            parts.append("")  # trailing empty

    host = ".".join(parts)
    host = maybe_trailing_dot(host, rng)
    return host


def maybe_port(rng: random.Random) -> str:
    if rng.random() < 0.35:
        # choose common/special ports and random ones
        ports = ["", "80", "443", "0", "65535", str(rng.randint(1, 65534))]
        p = rng.choice(ports)
        if p:
            return ":" + p
    return ""


def maybe_userinfo(rng: random.Random) -> str:
    if rng.random() < 0.25:
        # user[:pass]@
        user_chars = string.ascii_letters + string.digits + "._-"
        def rand_piece(min_len=1, max_len=8):
            ln = rng.randint(min_len, max_len)
            return ''.join(rng.choice(user_chars) for _ in range(ln))
        user = rand_piece()
        if rng.random() < 0.5:
            pwd = rand_piece(0, 8)  # allow empty password
            return f"{user}:{pwd}@"
        return f"{user}@"
    return ""


def maybe_scheme(rng: random.Random) -> str:
    if rng.random() < 0.4:
        schemes = [
            "http://", "https://", "ftp://", "ws://", "wss://",
            "file://", "mailto:", "ssh://", "git://",
        ]
        return rng.choice(schemes)
    return ""


def maybe_path_query_fragment(rng: random.Random) -> str:
    s = []
    # path
    if rng.random() < 0.6:
        seg_chars = string.ascii_letters + string.digits + "._-~%"
        segs = []
        for _ in range(rng.randint(0, 4)):
            ln = rng.randint(0, 10)
            seg = ''.join(rng.choice(seg_chars) for _ in range(ln))
            segs.append(seg)
        s.append("/" + "/".join(segs))
    # query
    if rng.random() < 0.6:
        kv_chars = string.ascii_letters + string.digits + "._-~%"
        pairs = []
        for _ in range(rng.randint(0, 4)):
            k = ''.join(rng.choice(kv_chars) for _ in range(rng.randint(0, 8)))
            v = ''.join(rng.choice(kv_chars) for _ in range(rng.randint(0, 8)))
            pairs.append(f"{k}={v}")
        s.append("?" + "&".join(pairs))
    # fragment
    if rng.random() < 0.4:
        frag_chars = string.ascii_letters + string.digits + "._-~%"
        frag = ''.join(rng.choice(frag_chars) for _ in range(rng.randint(0, 12)))
        s.append("#" + frag)
    return "".join(s)


def clamp_size(b: bytes) -> bytes:
    if len(b) <= MAX_TOTAL_BYTES:
        return b
    return b[:MAX_TOTAL_BYTES]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose between generating a bare host string (best for IDNA functions)
    # and a full URL that still starts with a host for broader coverage.
    choice = rng.random()
    if choice < 0.7:
        host = build_host(rng)
        out = host
    else:
        scheme = maybe_scheme(rng)
        userinfo = maybe_userinfo(rng)
        host = build_host(rng)
        port = maybe_port(rng)
        tail = maybe_path_query_fragment(rng)
        out = f"{scheme}{userinfo}{host}{port}{tail}"

    # Randomly pick from explicit punycode samples to ensure we hit to-Unicode path
    if rng.random() < 0.25:
        sample = rng.choice(PUNYCODE_HOST_SAMPLES)
        # sometimes combine with another label to exercise multi-label parsing
        if rng.random() < 0.5:
            out = sample
        else:
            suffix = build_host(rng)
            out = sample + "." + suffix.strip('.')

    # Ensure it's a valid UTF-8 Python string; encode to UTF-8 bytes for the fuzzer buffer
    data = out.encode('utf-8', errors='strict')

    # Optionally trim to a random length to exercise partial buffers including empty
    if rng.random() < 0.3:
        cut = rng.randint(0, len(data))
        data = data[:cut]

    return clamp_size(data)

import random
import string
from typing import List

# Generator for URL query keys/values. The fuzz stubs request std::string buffers
# and then pick a length up to size(). Our goal is to return bytes that, when
# split by the fuzzer into k and v, often form valid and interesting URL
# search parameters content.
#
# We produce a corpus-like concatenation of multiple candidate key/value tokens
# separated with NULs so FUZZ_PARAM_STR slices can land on diverse substrings.
# Each token is a plausible query key or value, including edge cases like empty,
# unicode, percent-encoded, spaces, reserved characters, repeated keys, etc.

SAFE_ASCII = string.ascii_letters + string.digits + "-_.*"
RESERVED = "!$'()*,;:@&=+?/[]%#"  # characters that often trigger encoding/splitting paths


def _pct_encode_random(rng: random.Random, s: str) -> str:
    # Percent-encode a random subset of bytes in UTF-8 form
    b = s.encode('utf-8', errors='strict')
    out = []
    for by in b:
        if rng.random() < 0.35 or by in b" %#&=+?;\"":
            out.append("%" + format(by, "02X"))
        else:
            out.append(chr(by) if 32 <= by <= 126 and chr(by) != '%' else "%" + format(by, "02X"))
    return ''.join(out)


def _rand_token(rng: random.Random, max_len: int = 64) -> str:
    choice = rng.randrange(10)
    if choice == 0:
        return ""  # empty value
    if choice == 1:
        # purely ascii safe
        n = rng.randint(1, min(32, max_len))
        return ''.join(rng.choice(SAFE_ASCII) for _ in range(n))
    if choice == 2:
        # reserved-heavy to exercise parsing/encoding
        n = rng.randint(1, min(24, max_len))
        return ''.join(rng.choice(SAFE_ASCII + RESERVED) for _ in range(n))
    if choice == 3:
        # unicode examples
        samples = [
            "café", "naïve", "東京", "😀", "👍🏽", "россия", "mañana", "παράδειγμα",
            "مثال", "डाटा", "đặc_biệt", "καλήμέρα"
        ]
        return rng.choice(samples)
    if choice == 4:
        # percent-encoded from ascii
        base = ''.join(rng.choice(SAFE_ASCII + " ") for _ in range(rng.randint(1, min(24, max_len))))
        return _pct_encode_random(rng, base)
    if choice == 5:
        # percent-encoded from unicode
        base = _rand_token(rng, max_len)
        return _pct_encode_random(rng, base)
    if choice == 6:
        # numeric-like
        return str(rng.randrange(0, 10**rng.randint(1, 8)))
    if choice == 7:
        # boolean-like
        return rng.choice(["true", "false", "on", "off", "1", "0", "yes", "no"])
    if choice == 8:
        # path-like
        segs = [ ''.join(rng.choice(SAFE_ASCII) for _ in range(rng.randint(1, 6))) for _ in range(rng.randint(1, 4)) ]
        return "/".join(segs)
    # mixed with equals/ampersand inside value to test delimiters
    parts = [ ''.join(rng.choice(SAFE_ASCII) for _ in range(rng.randint(1, 6))) for _ in range(rng.randint(2, 4)) ]
    delim = rng.choice(['&', '=', ';'])
    return delim.join(parts)


def _build_query_strings(rng: random.Random) -> List[str]:
    entries = []
    # Create several query pairs to enable operations like append/set/remove/has_value
    count = rng.randint(3, 10)
    # include intentional duplicates for same key
    base_keys = [ _rand_token(rng, 24) for _ in range(max(1, count // 2)) ]
    for i in range(count):
        if rng.random() < 0.6 and base_keys:
            k = rng.choice(base_keys)
        else:
            k = _rand_token(rng, 24)
        v = _rand_token(rng, 48)
        # sometimes include empty key or value explicitly
        if rng.random() < 0.1:
            k = ""
        if rng.random() < 0.15:
            v = ""
        entries.append((k, v))
    # Build a canonical query string with various separators
    sep = rng.choice(['&', ';'])
    query = sep.join([
        (k + ("=" + v if rng.random() < 0.85 else "")) for (k, v) in entries
    ])
    # with and without leading '?'
    q_with = '?' + query
    q_without = query
    # individual keys/values to serve as FUZZ_PARAM_STR sources as well
    tokens: List[str] = []
    tokens.extend([t for pair in entries for t in pair])
    tokens.extend([q_with, q_without])
    # Add standalone patterns
    tokens.extend([
        "key=value", "a=b&c=d", "empty=", "=novalue", "dup=1&dup=2", "percent=%20%2F%25",
        "k=v#frag", "k=v?inner", "space=hello world", _pct_encode_random(rng, "sp ec ial"),
    ])
    return tokens


def _pack_tokens_as_bytes(tokens: List[str], max_bytes: int, rng: random.Random) -> bytes:
    # Join tokens with NUL separators so substrings are independent. Also append
    # a trailing NUL-terminated region because some code expects C-strings.
    # Ensure size <= max_bytes.
    # Randomize order to vary coverage for a given seed.
    rng.shuffle(tokens)
    b = bytearray()
    for t in tokens:
        tb = t.encode('utf-8', errors='strict')
        # limit overly long tokens
        if len(tb) > 256:
            tb = tb[:256]
        if len(b) + len(tb) + 1 > max_bytes:
            break
        b.extend(tb)
        b.append(0)  # NUL separator
    if not b:
        b.extend(b"\0")
    # Ensure there is at least one additional NUL to form an empty string slice possibility
    if b[-1] != 0:
        b.append(0)
    return bytes(b)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    tokens = _build_query_strings(rng)
    # Add extra randomized tokens
    for _ in range(rng.randint(3, 8)):
        tokens.append(_rand_token(rng, 48))
    # Some keys and values commonly used
    tokens.extend([
        "id", "user", "session", "token", "redirect", "callback",
        "page", "limit", "offset", "sort", "order", "filter",
        "中文", "ключ", "ключ=%D1%82est",
    ])
    return _pack_tokens_as_bytes(tokens, 4096, rng)
